const CLANS = {"ashikaga":{"en":"Ashikaga","ja":"足利","dye":"fuji","motif":"plain","title":"The shogunate","short":"The house of the shoguns since 1338. By 1467 the Ashikaga reigned from Kyoto but no longer ruled; the Ōnin War, fought in their own capital, showed the realm that nobody had to obey them."},"hosokawa":{"en":"Hosokawa","ja":"細川","dye":"matsuba","motif":"dots","title":"Leaders of the Eastern Army","short":"The most powerful shugo house in 1467, holding the provinces around Kyoto and Shikoku. Hosokawa Katsumoto led the Eastern Army; his son ruled the capital until the clan tore itself apart."},"yamana":{"en":"Yamana","ja":"山名","dye":"bengara","motif":"plain","title":"Leaders of the Western Army","short":"Masters of a band of western provinces in 1467. Yamana Sōzen led the Western Army; afterwards the clan faded slowly, holding Tajima and Inaba until Hideyoshi took them in 1580–81."},"hatakeyama":{"en":"Hatakeyama","ja":"畠山","dye":"hiwa","motif":"dots","title":"A succession split in two","short":"A great shugo house whose two rival heirs, Masanaga and Yoshinari, took opposite sides in 1467. Their feud outlived the war by decades and drained the clan."},"shiba":{"en":"Shiba","ja":"斯波","dye":"kuchiba","motif":"dots","title":"Governors overthrown by their deputies","short":"In 1467 the Shiba governed Echizen, Owari and Tōtōmi. Within fifty years they had lost all three to their own deputies and neighbours: the Asakura, the Oda and the Imagawa."},"ouchi":{"en":"Ōuchi","ja":"大内","dye":"suo","motif":"kikko","title":"The wealth of the western sea","short":"Lords of Suō and Nagato who grew rich on trade with Ming China and Korea, and made Yamaguchi a \"little Kyoto\". A coup in 1551 ended them, and the Mōri took their lands."},"akamatsu":{"en":"Akamatsu","ja":"赤松","dye":"beni","motif":"plain","title":"The restored house","short":"Destroyed in 1441 for murdering a shogun, restored by the Eastern Army in 1467–68. They held Harima, Bizen and Mimasaka until their deputies, the Urakami, overthrew them."},"kyogoku":{"en":"Kyōgoku","ja":"京極","dye":"asagi","motif":"dots","title":"Northern Ōmi and the San'in","short":"In 1467 the Kyōgoku held northern Ōmi, Hida, Izumo and Oki and fought for the East. Their own deputies, the Amago in Izumo and the Azai in Ōmi, took everything from them."},"rokkaku":{"en":"Rokkaku","ja":"六角","dye":"shikon","motif":"dots","title":"Southern Ōmi","short":"Governors of southern Ōmi, astride the roads into Kyoto. They held out for a century, then fell in weeks when Nobunaga marched on the capital in 1568."},"toki":{"en":"Toki","ja":"土岐","dye":"kihada","motif":"dots","title":"Mino before the Saitō","short":"Governors of Mino for two centuries, until the oil merchant's son Saitō Dōsan pushed the last of them out around 1542."},"isshiki":{"en":"Isshiki","ja":"一色","dye":"suo","motif":"plain","title":"Tango","short":"A Western Army house that kept the small province of Tango until Hosokawa Fujitaka and Akechi Mitsuhide took it for Nobunaga in 1579."},"wtakeda":{"en":"Takeda of Wakasa","ja":"若狭武田","dye":"akane","motif":"dots","title":"A small coastal house","short":"A branch of the Takeda that governed Wakasa on the Sea of Japan for a century, fought for the East in 1467, and became Oda vassals in the 1570s."},"kitabatake":{"en":"Kitabatake","ja":"北畠","dye":"uguisu","motif":"plain","title":"Court nobles turned warlords","short":"Descendants of a famous court family who ruled southern Ise for two centuries. Nobunaga absorbed them by forcing them to adopt his son in 1569, then had them killed in 1576."},"urakami":{"en":"Urakami","ja":"浦上","dye":"tobi","motif":"dots","title":"The deputies who rose","short":"Deputies of the Akamatsu who seized Bizen in 1521, then lost it in turn to their own retainer, Ukita Naoie, in 1575."},"kono":{"en":"Kōno","ja":"河野","dye":"asagi","motif":"kikko","title":"Iyo and the Inland Sea","short":"An old house of Iyo with sea-lord allies on the Inland Sea. They held on through the whole period, allied with the Mōri, until Chōsokabe and then Hideyoshi took Iyo in 1585."},"imagawa":{"en":"Imagawa","ja":"今川","dye":"murasaki","motif":"plain","title":"The first of the Tōkaidō","short":"A branch of the Ashikaga that ruled Suruga, took Tōtōmi and Mikawa, and under Imagawa Yoshimoto was the strongest house on the Pacific road. Yoshimoto's death at Okehazama in 1560 began their fall."},"takeda":{"en":"Takeda","ja":"武田","dye":"akane","motif":"hishi","title":"The mountain province of Kai","short":"Under Takeda Shingen the clan of Kai built one of the strongest armies of the age, took Shinano and Suruga, and defeated Tokugawa at Mikatagahara. Defeat at Nagashino in 1575 began their end; Oda armies destroyed them in 1582."},"uesugi":{"en":"Uesugi","ja":"上杉","dye":"asagi","motif":"plain","title":"Echigo and the Kantō deputies","short":"In 1467 the Uesugi governed the Kantō for the shogunate and held Echigo. Driven from the Kantō by the Hōjō, they passed their name to their Echigo deputy, Nagao Kagetora, who became Uesugi Kenshin."},"hojo":{"en":"Hōjō","ja":"北条","dye":"kariyasu","motif":"uroko","title":"Five generations at Odawara","short":"Founded by an adventurer who took Izu in 1493 and Odawara in 1495, the Hōjō built the best-governed realm in the Kantō over five generations, until Hideyoshi besieged Odawara in 1590."},"satake":{"en":"Satake","ja":"佐竹","dye":"yomogi","motif":"dots","title":"Hitachi","short":"An old house of Hitachi that fought the Hōjō for decades, joined Hideyoshi in time, and ruled all of Hitachi in the 1590s. Wavering in 1600 cost them: Tokugawa moved them north to Akita in 1602."},"satomi":{"en":"Satomi","ja":"里見","dye":"kaki","motif":"plain","title":"Awa across the bay","short":"Lords of Awa at the tip of the Bōsō peninsula, enemies of the Hōjō across Edo Bay for a century, with fleets on the bay."},"oda":{"en":"Oda","ja":"織田","dye":"yamabuki","motif":"plain","title":"The unifier","short":"Deputies in Owari who, under Oda Nobunaga, rose to hold most of central Japan: Okehazama (1560), Kyoto (1568), Nagashino (1575). Nobunaga died at Honnō-ji in 1582 with unification in sight."},"tokugawa":{"en":"Tokugawa","ja":"徳川","dye":"matsuba","motif":"plain","title":"The patient one","short":"Born Matsudaira, a hostage of the Imagawa, Tokugawa Ieyasu broke free after Okehazama, stood by Nobunaga for twenty years, outlasted Hideyoshi, won Sekigahara in 1600 and became shogun in 1603."},"saito":{"en":"Saitō","ja":"斎藤","dye":"tobi","motif":"plain","title":"The viper of Mino","short":"Saitō Dōsan made himself master of Mino around 1542 by pushing out the Toki governors. Three generations later, Nobunaga took Mino from his grandson in 1567."},"asakura":{"en":"Asakura","ja":"朝倉","dye":"yomogi","motif":"plain","title":"Echizen","short":"Deputies of the Shiba who changed sides in the Ōnin War and were made masters of Echizen in 1471. Their castle town Ichijōdani flourished for a century until Nobunaga burned it in 1573."},"azai":{"en":"Azai","ja":"浅井","dye":"beni","motif":"dots","title":"Northern Ōmi","short":"Retainers of the Kyōgoku who took northern Ōmi in the 1520s. Azai Nagamasa married Nobunaga's sister Oichi, then broke with him in 1570 to stand by the Asakura; Odani fell in 1573."},"ikko":{"en":"Ikkō-ikki","ja":"一向一揆","dye":"fuji","motif":"dots","title":"The leagues of the faithful","short":"Leagues of farmers, priests and small warriors of the True Pure Land sect. They ruled Kaga for nearly a century from 1488 and, from Ishiyama Hongan-ji in Osaka, fought Nobunaga for ten years."},"miyoshi":{"en":"Miyoshi","ja":"三好","dye":"kaki","motif":"kikko","title":"Masters of Kyoto before Nobunaga","short":"Deputies of the Hosokawa from Awa in Shikoku who seized Kyoto in 1549. Under Miyoshi Nagayoshi they ruled the capital and eight provinces; after his death in 1564 they split, and Nobunaga drove them out."},"mori":{"en":"Mōri","ja":"毛利","dye":"murasaki","motif":"kikko","title":"Ten provinces of the west","short":"Small lords of Aki who, under Mōri Motonari, beat the Sue at Itsukushima (1555), took the Ōuchi lands, crushed the Amago (1566), and ruled most of western Honshū. They led the Western Army, in name, in 1600."},"amago":{"en":"Amago","ja":"尼子","dye":"yomogi","motif":"kikko","title":"Gassan-Toda","short":"Deputies of the Kyōgoku who took Izumo from their masters and, under Amago Tsunehisa and Haruhisa, dominated the San'in. The Mōri took their fortress of Gassan-Toda in 1566."},"ukita":{"en":"Ukita","ja":"宇喜多","dye":"beni","motif":"kikko","title":"Bizen","short":"Ukita Naoie took Bizen from his own lords, the Urakami, in 1575 and switched from the Mōri to Nobunaga in 1579. His son Hideie was raised by Hideyoshi, led the Western Army's largest force at Sekigahara, and was exiled."},"chosokabe":{"en":"Chōsokabe","ja":"長宗我部","dye":"tobi","motif":"kikko","title":"All of Shikoku","short":"Chōsokabe Motochika rose from one of seven small houses in Tosa to master nearly all of Shikoku by 1585, only to lose three of its four provinces to Hideyoshi that same year."},"otomo":{"en":"Ōtomo","ja":"大友","dye":"bengara","motif":"kikko","title":"Bungo and the Christian lord","short":"Lords of Bungo who, under Ōtomo Sōrin, held six provinces of northern Kyushu and welcomed Portuguese traders and Jesuits. A disaster at Mimigawa in 1578 broke them; Hideyoshi's 1587 campaign saved them, briefly."},"ryuzoji":{"en":"Ryūzōji","ja":"龍造寺","dye":"matsuba","motif":"kikko","title":"The bear of Hizen","short":"Ryūzōji Takanobu built a realm in Hizen and, after the Ōtomo collapse, much of northern Kyushu. He was killed at Okitanawate in 1584; his retainer Nabeshima Naoshige inherited the clan's lands."},"shimazu":{"en":"Shimazu","ja":"島津","dye":"kariyasu","motif":"plain","title":"The far south","short":"Lords of Satsuma since the twelfth century. Four brothers led them north through Kyushu, winning at Mimigawa (1578) and Okitanawate (1584), until Hideyoshi's armies forced them back in 1587. They fought for the West in 1600 and still kept their lands."},"so":{"en":"Sō","ja":"宗","dye":"uguisu","motif":"kikko","title":"Tsushima, between Japan and Korea","short":"Lords of Tsushima who lived by trade with Korea, and were caught in the middle when Hideyoshi invaded Korea in 1592."},"date":{"en":"Date","ja":"伊達","dye":"akane","motif":"plain","title":"The north","short":"Lords of southern Mutsu. Date Masamune, the \"One-Eyed Dragon\", conquered the Ashina in 1589, came late to Hideyoshi at Odawara, kept his head, and sided with Tokugawa in 1600."},"toyotomi":{"en":"Toyotomi","ja":"豊臣","dye":"kihada","motif":"kikko","title":"The peasant who ruled Japan","short":"Hashiba Hideyoshi rose from foot soldier to Nobunaga's best general, avenged him in 1582, and unified Japan by 1590 as regent under the name Toyotomi. He died in 1598 during his war in Korea, leaving a five-year-old heir."},"maeda":{"en":"Maeda","ja":"前田","dye":"beni","motif":"hishi","title":"Kaga, a million koku","short":"Maeda Toshiie, Nobunaga's companion and Hideyoshi's friend, was given Noto in 1581 and Kaga in 1583. His heirs sided with Tokugawa and kept the richest domain in Japan."},"kobayakawa":{"en":"Kobayakawa","ja":"小早川","dye":"ume","motif":"uroko","title":"The Mōri branch that decided Sekigahara","short":"A Mōri branch line. Kobayakawa Takakage held Iyo, then Chikuzen; his adopted heir Hideaki, Hideyoshi's nephew, turned on the Western Army in mid-battle at Sekigahara."},"east":{"en":"Eastern Army","ja":"東軍","dye":"matsuba","motif":"hishi","title":"Tokugawa and his allies, 1600","short":"The coalition Tokugawa Ieyasu led in 1600: his own Kantō forces and Hideyoshi's generals who hated Ishida Mitsunari, among them Fukushima, Kuroda, Katō, Hosokawa, Ikeda and Date."},"west":{"en":"Western Army","ja":"西軍","dye":"bengara","motif":"dots","title":"Ishida Mitsunari's coalition, 1600","short":"The coalition Ishida Mitsunari raised in Hideyori's name in 1600, nominally headed by Mōri Terumoto, with Ukita, Shimazu, Konishi, Ōtani and Chōsokabe; it fell apart at Sekigahara when its own allies defected."},"tozama":{"en":"Allied lords (tozama)","ja":"外様","dye":"tobi","motif":"hishi","title":"The lords outside the Tokugawa house","short":"After 1600, the lords who had fought beside Tokugawa but were not his hereditary vassals: Fukushima, Kuroda, Hosokawa, Katō, Ikeda, Yamauchi and others. Rewarded with big western domains, kept away from the centre."},"imperial":{"en":"Imperial army","ja":"新政府軍","dye":"kariyasu","motif":"kikko","title":"Satsuma, Chōshū and the new government, 1868","short":"The side that fought for the emperor in the Boshin War of 1868–69, led by Satsuma and Chōshū with Tosa and Hizen, under the brocade banner the emperor's court granted them."},"shogunate":{"en":"Shogunate forces","ja":"旧幕府軍","dye":"matsuba","motif":"uroko","title":"The Tokugawa side and the northern alliance, 1868","short":"The forces that fought on for the Tokugawa in 1868–69: the shogun's own troops, Aizu, and the alliance of northern domains, ending with a short-lived republic in Ezo."},"empire":{"en":"Empire of Japan","ja":"大日本帝国","dye":"rikyu","motif":"dots","title":"The modern state, 1871–1945","short":"The modern Japanese state: in 1871 the domains were abolished and replaced by prefectures governed from Tokyo, and the old provinces lived on only as names."},"rebels":{"en":"Satsuma rebels","ja":"薩摩軍","dye":"bengara","motif":"hishi","title":"Saigō Takamori's last war, 1877","short":"The army of former Satsuma samurai who rose under Saigō Takamori in 1877, the last and largest revolt against the Meiji state."}};
