const EVENTS = [{"id":"kamigoryo","year":1467,"en":"The Ōnin War begins","ja":"応仁の乱","at":"yamashiro","sides":["hatakeyama","hatakeyama"],"winner":null,"short":"Two Hatakeyama heirs fight at Kamigoryō shrine in Kyoto, and the great houses take sides: the Eastern Army of Hosokawa Katsumoto against the Western Army of Yamana Sōzen."},{"id":"kaga","year":1488,"en":"The Kaga league takes a province","ja":"加賀一向一揆","at":"kaga","sides":[],"winner":null,"short":"The Ikkō league of Kaga besieges Takao castle and drives its governor, Togashi Masachika, to suicide."},{"id":"meio","year":1493,"en":"The Meiō coup","ja":"明応の政変","at":"yamashiro","sides":[],"winner":null,"short":"Hosokawa Masamoto deposes the shogun and installs his own candidate. From now on, shoguns are made by whoever holds Kyoto."},{"id":"izu","year":1493,"en":"Hōjō Sōun takes Izu","ja":"伊豆討ち入り","at":"izu","sides":[],"winner":null,"short":"Ise Shinkurō, later called Hōjō Sōun, crosses into Izu and overthrows the Horigoe kubō, the Ashikaga's governor of the east. Two years later he takes Odawara."},{"id":"eisho","year":1507,"en":"The murder of Hosokawa Masamoto","ja":"永正の錯乱","at":"yamashiro","sides":[],"winner":null,"short":"Hosokawa Masamoto, the man who had deposed a shogun, is murdered in his bath by retainers of one of his adopted heirs. The Hosokawa, the house that held the capital, split into warring lines."},{"id":"iwami","year":1526,"en":"Silver at Iwami","ja":"石見銀山","at":"iwami","sides":[],"winner":null,"short":"The merchant Kamiya Jutei begins to work a silver mine in the hills of Iwami. It becomes the largest silver mine in Japan's history."},{"id":"hokke","year":1536,"en":"Kyoto's Lotus temples burned","ja":"天文法華の乱","at":"yamashiro","sides":[],"winner":null,"short":"The warrior monks of Mount Hiei and the army of the Rokkaku burn all twenty-one temples of the Nichiren (Lotus) sect in Kyoto. The fire takes the whole of the lower city and a third of the upper."},{"id":"nobutora","year":1541,"en":"Shingen exiles his father","ja":"信虎追放","at":"kai","sides":[],"winner":null,"short":"Takeda Harunobu, the future Shingen, aged twenty, lets his father Nobutora ride to Suruga and bars the way home behind him. Nobutora does not see Kai again while his son lives."},{"id":"tanegashima","year":1543,"en":"Guns arrive at Tanegashima","ja":"鉄砲伝来","at":"osumi","sides":[],"winner":null,"short":"A ship carrying Portuguese traders, the first Europeans to reach Japan, lands on the island of Tanegashima. Its fifteen-year-old lord watches them shoot and sets his swordsmith to copy their guns."},{"id":"kawagoe","year":1546,"en":"Night battle of Kawagoe","ja":"河越夜戦","at":"musashi","sides":["hojo","uesugi"],"winner":"hojo","short":"A small Hōjō army breaks a huge Uesugi coalition besieging Kawagoe castle with a night attack, and the Hōjō become masters of the Kantō."},{"id":"uedahara","year":1548,"en":"Battle of Uedahara","ja":"上田原の戦い","at":"shinano","sides":["takeda"],"winner":null,"short":"Murakami Yoshikiyo beats Takeda Shingen in northern Shinano: Shingen's first defeat, and the first field battle in Japan where guns were used."},{"id":"eguchi","year":1549,"en":"Battle of Eguchi","ja":"江口の戦い","at":"settsu","sides":["miyoshi","hosokawa"],"winner":"miyoshi","short":"Miyoshi Nagayoshi turns on his lord Hosokawa Harumoto and destroys his kinsman Miyoshi Masanaga at Eguchi. Harumoto and the shogun flee Kyoto; the Miyoshi, once Hosokawa retainers, now hold the capital."},{"id":"xavier","year":1549,"en":"Francis Xavier lands at Kagoshima","ja":"ザビエル来日","at":"satsuma","sides":[],"winner":null,"short":"The Jesuit Francis Xavier comes ashore at Kagoshima with three companions and a Japanese convert, Anjirō, and begins the first Christian mission to Japan."},{"id":"taineiji","year":1551,"en":"The fall of Ōuchi Yoshitaka","ja":"大寧寺の変","at":"nagato","sides":[],"winner":null,"short":"Sue Harukata, the Ōuchi's leading general, rises against his lord. Yoshitaka flees and dies at Tainei-ji temple. The richest house of the west falls from within."},{"id":"itsukushima","year":1555,"en":"Battle of Itsukushima","ja":"厳島の戦い","at":"aki","sides":["mori","ouchi"],"winner":"mori","short":"Mōri Motonari lures Sue Harukata's much larger army onto the sacred island of Itsukushima and destroys it in a dawn attack in a storm."},{"id":"okehazama","year":1560,"en":"Battle of Okehazama","ja":"桶狭間の戦い","at":"owari","sides":["oda","imagawa"],"winner":"oda","short":"Oda Nobunaga, 25 and outnumbered by perhaps ten to one, surprises Imagawa Yoshimoto's army resting in a narrow valley during a storm, and kills him."},{"id":"kawanakajima","year":1561,"en":"Fourth battle of Kawanakajima","ja":"第四次川中島の戦い","at":"shinano","sides":["takeda","uesugi"],"winner":null,"short":"The bloodiest of five meetings between Takeda Shingen and Uesugi Kenshin on the plain of Kawanakajima in northern Shinano. Both sides lost thousands, and neither won."},{"id":"konodai","year":1564,"en":"Second battle of Kōnodai","ja":"第二次国府台合戦","at":"shimosa","sides":["hojo","satomi"],"winner":"hojo","short":"The Hōjō defeat the Satomi on the heights of Kōnodai, by the bay, and take control of Shimōsa and much of Kazusa."},{"id":"gassantoda","year":1566,"en":"Fall of Gassan-Toda","ja":"月山富田城の戦い","at":"izumo","sides":["mori","amago"],"winner":"mori","short":"After a long siege, Amago Yoshihisa surrenders the mountain fortress of Gassan-Toda to Mōri Motonari. The Amago realm ends."},{"id":"inabayama","year":1567,"en":"Nobunaga takes Mino","ja":"稲葉山城の戦い","at":"mino","sides":["oda","saito"],"winner":"oda","short":"After years of attacks, Nobunaga takes Inabayama castle from Saitō Tatsuoki, renames it Gifu, and adopts a seal reading \"rule the realm by force\"."},{"id":"kyoto1568","year":1568,"en":"Nobunaga enters Kyoto","ja":"織田信長の上洛","at":"yamashiro","sides":[],"winner":null,"short":"Nobunaga marches on the capital with Ashikaga Yoshiaki, sweeps aside the Rokkaku and the Miyoshi, and makes Yoshiaki shogun."},{"id":"anegawa","year":1570,"en":"Battle of Anegawa","ja":"姉川の戦い","at":"omi","sides":["oda","azai"],"winner":"oda","short":"Oda and Tokugawa beat the Azai and Asakura on the banks of the Ane river, but cannot yet finish them."},{"id":"honganji","year":1570,"en":"The Ishiyama Hongan-ji war begins","ja":"石山合戦","at":"settsu","sides":[],"winner":null,"short":"The fortress-temple of the True Pure Land sect in Osaka rises against Nobunaga. It holds out for ten years."},{"id":"hiei","year":1571,"en":"Mount Hiei burned","ja":"比叡山焼き討ち","at":"omi","sides":[],"winner":null,"short":"Nobunaga burns the great monastery of Enryaku-ji on Mount Hiei, which had sheltered his enemies, killing thousands of monks and lay people."},{"id":"mikatagahara","year":1573,"en":"Battle of Mikatagahara","ja":"三方ヶ原の戦い","at":"totomi","sides":["takeda","tokugawa"],"winner":"takeda","short":"Takeda Shingen crushes Tokugawa Ieyasu on a plateau north of Hamamatsu. It is Ieyasu's worst defeat; Shingen dies a few months later."},{"id":"end_muromachi","year":1573,"en":"The last shogun is driven out","ja":"室町幕府の滅亡","at":"yamashiro","sides":[],"winner":null,"short":"Ashikaga Yoshiaki rises against Nobunaga, is defeated and expelled from Kyoto. The Muromachi shogunate ends after 235 years. Later that year the Azai and Asakura are destroyed."},{"id":"nagashino","year":1575,"en":"Battle of Nagashino","ja":"長篠の戦い","at":"mikawa","sides":["oda","takeda"],"winner":"oda","short":"Oda and Tokugawa guns, firing from behind wooden palisades, destroy Takeda Katsuyori's army as it attacks across open ground. Many of the Takeda's senior generals die."},{"id":"tedorigawa","year":1577,"en":"Battle of Tedorigawa","ja":"手取川の戦い","at":"kaga","sides":["uesugi","oda"],"winner":"uesugi","short":"Uesugi Kenshin catches Shibata Katsuie's Oda army at the Tedori river in Kaga; the Oda lose about a thousand men. It is Kenshin's last battle: he dies the next spring."},{"id":"mimigawa","year":1578,"en":"Battle of Mimigawa","ja":"耳川の戦い","at":"hyuga","sides":["shimazu","otomo"],"winner":"shimazu","short":"The Shimazu destroy the great Ōtomo army sent into Hyūga, and northern Kyushu begins to fall away from the Ōtomo."},{"id":"tottori","year":1581,"en":"Siege of Tottori","ja":"鳥取城の戦い","at":"inaba","sides":["oda","mori"],"winner":"oda","short":"Hideyoshi surrounds Tottori castle after buying up the region's rice, and starves the Mōri garrison into surrender."},{"id":"tenmokuzan","year":1582,"en":"The end of the Takeda","ja":"武田氏滅亡","at":"kai","sides":["oda","takeda"],"winner":"oda","short":"Oda and Tokugawa armies invade the Takeda lands. Vassals defect, castles fall, and Takeda Katsuyori dies with his family at Tenmokuzan."},{"id":"honnoji","year":1582,"en":"The Honnō-ji incident","ja":"本能寺の変","at":"yamashiro","sides":["oda","oda"],"winner":null,"short":"At dawn on 21 June 1582, Nobunaga's general Akechi Mitsuhide surrounds the temple of Honnō-ji in Kyoto, where Nobunaga is staying with a small guard. Nobunaga dies in the burning temple."},{"id":"yamazaki","year":1582,"en":"Battle of Yamazaki","ja":"山崎の戦い","at":"yamashiro","sides":["toyotomi","oda"],"winner":"toyotomi","short":"Hideyoshi makes peace with the Mōri, races his army back east in days, and destroys Akechi Mitsuhide at Yamazaki. Mitsuhide is killed fleeing."},{"id":"shizugatake","year":1583,"en":"Battle of Shizugatake","ja":"賤ヶ岳の戦い","at":"omi","sides":["toyotomi","oda"],"winner":"toyotomi","short":"Hideyoshi defeats Shibata Katsuie in the mountains of northern Ōmi and becomes Nobunaga's real successor. Katsuie dies at his castle with his wife Oichi."},{"id":"komaki","year":1584,"en":"Komaki and Nagakute","ja":"小牧・長久手の戦い","at":"owari","sides":["tokugawa","toyotomi"],"winner":null,"short":"Tokugawa Ieyasu and Oda Nobukatsu face Hideyoshi for months. Ieyasu wins the one big clash, at Nagakute, but the campaign ends in a negotiated peace."},{"id":"okitanawate","year":1584,"en":"Battle of Okitanawate","ja":"沖田畷の戦い","at":"hizen","sides":["shimazu","ryuzoji"],"winner":"shimazu","short":"Shimazu Iehisa and Arima Harunobu trap Ryūzōji Takanobu's far larger army on narrow paths through the marshes of Shimabara. Takanobu is killed."},{"id":"shikoku","year":1585,"en":"The conquest of Shikoku","ja":"四国征伐","at":"awa_shikoku","sides":[],"winner":null,"short":"Hideyoshi sends over 100,000 men into Shikoku. Chōsokabe Motochika, who had just united the island, surrenders and keeps only Tosa."},{"id":"kyushu","year":1587,"en":"The conquest of Kyushu","ja":"九州平定","at":"satsuma","sides":[],"winner":null,"short":"Hideyoshi leads a vast army into Kyushu at the Ōtomo's request. The Shimazu, who had taken almost the whole island, surrender and are cut back to Satsuma and Ōsumi."},{"id":"suriagehara","year":1589,"en":"Battle of Suriagehara","ja":"摺上原の戦い","at":"mutsu","sides":["date"],"winner":"date","short":"Date Masamune destroys the Ashina at Suriagehara and takes Aizu, becoming master of southern Mutsu, just before Hideyoshi reaches the north."},{"id":"odawara","year":1590,"en":"The siege of Odawara","ja":"小田原征伐","at":"sagami","sides":["toyotomi","hojo"],"winner":"toyotomi","short":"Hideyoshi besieges the Hōjō capital with over 200,000 men. Odawara surrenders after three months. The whole country now obeys one ruler."},{"id":"korea","year":1592,"en":"The invasions of Korea","ja":"文禄・慶長の役","at":"tsushima","sides":[],"winner":null,"short":"Hideyoshi sends armies across the strait to invade Korea, aiming at Ming China. The war devastates Korea and ends with his death in 1598."},{"id":"hideyoshi_dies","year":1598,"en":"Hideyoshi dies","ja":"秀吉の死","at":"yamashiro","sides":[],"winner":null,"short":"Toyotomi Hideyoshi dies at Fushimi, leaving his five-year-old son Hideyori in the care of five elders and five commissioners. Tokugawa Ieyasu is the strongest of them."},{"id":"sekigahara","year":1600,"en":"Battle of Sekigahara","ja":"関ヶ原の戦い","at":"mino","sides":["east","west"],"winner":"east","short":"On 21 October 1600, in a foggy valley in Mino, the Eastern Army of Tokugawa Ieyasu meets Ishida Mitsunari's Western Army. When Kobayakawa Hideaki turns on his own side, the West collapses."},{"id":"shogun","year":1603,"en":"Ieyasu becomes shogun","ja":"江戸幕府の成立","at":"musashi","sides":[],"winner":null,"short":"The emperor names Tokugawa Ieyasu shogun. His government at Edo will rule Japan for 265 years."},{"id":"ryukyu1609","year":1609,"en":"Satsuma invades Ryukyu","ja":"琉球侵攻","at":"ryukyu","sides":["shimazu"],"winner":"shimazu","short":"With the shogun's leave, the Shimazu of Satsuma send some 3,000 men in a hundred ships against the kingdom of Ryukyu and take its royal castle at Shuri. Ryukyu keeps its king but answers to Satsuma from now on."},{"id":"osaka","year":1615,"en":"The fall of Osaka","ja":"大坂の陣","at":"settsu","sides":["tokugawa","toyotomi"],"winner":"tokugawa","short":"Tokugawa Ieyasu besieges Toyotomi Hideyori in Osaka castle in the winter of 1614 and storms it in the summer of 1615. Hideyori and his mother die as the castle burns; the Toyotomi line ends."},{"id":"sankin","year":1635,"en":"Alternate attendance","ja":"参勤交代","at":"musashi","sides":[],"winner":null,"short":"Shogun Tokugawa Iemitsu makes it law that every lord spend alternate years in Edo, leaving his wife and heir there as hostages."},{"id":"shimabara","year":1637,"en":"The Shimabara Rebellion","ja":"島原の乱","at":"hizen","sides":["tokugawa"],"winner":"tokugawa","short":"Peasants and Christians of Shimabara and Amakusa, crushed by taxes and persecution, rise under the teenage Amakusa Shirō and hold out in Hara castle until April 1638."},{"id":"sakoku","year":1639,"en":"The country closed","ja":"鎖国","at":"hizen","sides":[],"winner":null,"short":"The Portuguese are expelled. From 1641 the Dutch are confined to the little island of Dejima in Nagasaki harbour, and for two centuries Japanese may not leave the country."},{"id":"meireki","year":1657,"en":"The Great Fire of Meireki","ja":"明暦の大火","at":"musashi","sides":[],"winner":null,"short":"Fire sweeps through Edo for three days, destroying most of the city and the keep of Edo castle. Over 100,000 people are thought to have died."},{"id":"shakushain","year":1669,"en":"Shakushain's war","ja":"シャクシャインの戦い","at":"ezo","sides":[],"winner":null,"short":"The Ainu chief Shakushain calls the Ainu of Ezo to rise against the Matsumae, the Japanese lords who control their trade. By the end of the year he has been killed by Matsumae warriors."},{"id":"ako","year":1703,"en":"The forty-seven rōnin","ja":"赤穂事件","at":"musashi","sides":[],"winner":null,"short":"Forty-seven retainers of the lord of Akō avenge their master by killing the courtier Kira Yoshinaka in Edo, then forty-six of them are ordered to commit seppuku."},{"id":"hoei","year":1707,"en":"Mount Fuji erupts","ja":"宝永大噴火","at":"suruga","sides":[],"winner":null,"short":"Fuji's last eruption, weeks after one of the largest earthquakes in Japan's history. Ash falls on Edo, a hundred kilometres away."},{"id":"kaitai","year":1774,"en":"A Dutch anatomy in Japanese","ja":"解体新書","at":"musashi","sides":[],"winner":null,"short":"Sugita Genpaku and Maeno Ryōtaku publish Kaitai Shinsho, a translation of a Dutch book of anatomy: the first full translation of a Western book into Japanese. \"Dutch learning\" takes off."},{"id":"tenmei","year":1782,"en":"The Tenmei famine","ja":"天明の大飢饉","at":"mutsu","sides":[],"winner":null,"short":"Cold summers and the eruption of Mount Asama in 1783 bring years of famine. The north-east suffers worst; hundreds of thousands die."},{"id":"laxman","year":1792,"en":"A Russian ship at Nemuro","ja":"ラクスマン来航","at":"ezo","sides":[],"winner":null,"short":"Adam Laxman sails into Nemuro to bring home Japanese castaways and ask for trade. He leaves with a paper allowing one Russian ship to call at Nagasaki, and the shogunate turns its eyes north."},{"id":"ino","year":1800,"en":"Inō Tadataka sets out","ja":"伊能忠敬の測量","at":"ezo","sides":[],"winner":null,"short":"Inō Tadataka, a retired sake brewer of fifty-five, leaves Edo at his own expense to survey the coast of Ezo. He spends the rest of his life walking and measuring Japan."},{"id":"siebold","year":1828,"en":"The Siebold incident","ja":"シーボルト事件","at":"hizen","sides":[],"winner":null,"short":"Philipp Franz von Siebold, the doctor of the Dutch post at Dejima, is found with maps of Japan drawn from Inō Tadataka's surveys, which no foreigner may own. He is accused of spying and expelled."},{"id":"oshio","year":1837,"en":"Ōshio Heihachirō's rising","ja":"大塩平八郎の乱","at":"settsu","sides":["tokugawa"],"winner":"tokugawa","short":"In the Tenpō famine a former police official of Osaka rises with townspeople and farmers to help the starving. The rising is crushed in a day, but a fifth of Osaka burns."},{"id":"perry","year":1853,"en":"The black ships","ja":"黒船来航","at":"sagami","sides":[],"winner":null,"short":"Commodore Matthew Perry anchors four American warships off Uraga and demands that Japan open its ports. He comes back the next year, and the shogunate signs."},{"id":"ansei","year":1858,"en":"The unequal treaties","ja":"安政の五カ国条約","at":"musashi","sides":[],"winner":null,"short":"Under pressure, the shogunate signs trade treaties with the United States, Britain, France, Russia and the Netherlands, without the emperor's approval, and crushes its critics."},{"id":"sakuradamon","year":1860,"en":"The Sakuradamon incident","ja":"桜田門外の変","at":"musashi","sides":[],"winner":null,"short":"Masterless samurai, most of them from Mito, kill the great elder Ii Naosuke in the snow outside Edo castle's Sakurada gate."},{"id":"kagoshima","year":1863,"en":"The bombardment of Kagoshima","ja":"薩英戦争","at":"satsuma","sides":["shimazu"],"winner":null,"short":"A British squadron shells Kagoshima after Satsuma men killed a British merchant. Satsuma learns how far behind it is, and soon buys British ships and guns."},{"id":"shimonoseki","year":1864,"en":"The Shimonoseki campaign","ja":"下関戦争","at":"nagato","sides":["mori"],"winner":null,"short":"Chōshū fires on foreign ships in the Shimonoseki strait; in 1864 a fleet of seventeen British, French, Dutch and American warships destroys its forts."},{"id":"taisei","year":1867,"en":"The shogun returns power","ja":"大政奉還","at":"yamashiro","sides":[],"winner":null,"short":"The fifteenth shogun, Tokugawa Yoshinobu, hands the powers of government back to the emperor, hoping to lead the new order. Two months later Satsuma and Chōshū declare the restoration of imperial rule."},{"id":"toba","year":1868,"en":"Toba–Fushimi and the Boshin War","ja":"戊辰戦争","at":"yamashiro","sides":["imperial","shogunate"],"winner":"imperial","short":"Outside Kyoto in January 1868 a smaller army of Satsuma and Chōshū, under the emperor's brocade banner, beats the shogunate's forces. Yoshinobu flees to Edo, and the civil war of 1868–69 begins."},{"id":"edo1868","year":1868,"en":"Edo surrenders","ja":"江戸開城","at":"musashi","sides":[],"winner":null,"short":"Katsu Kaishū for the shogunate and Saigō Takamori for the emperor agree to hand over Edo castle without a battle, sparing the city of a million people."},{"id":"aizu","year":1868,"en":"The siege of Aizu","ja":"会津戦争","at":"mutsu","sides":["imperial","shogunate"],"winner":"imperial","short":"The northern domains fight on. Aizu, the shogunate's most loyal domain, holds out in Wakamatsu castle for a month before surrendering in November."},{"id":"hakodate","year":1869,"en":"The battle of Hakodate","ja":"箱館戦争","at":"ezo","sides":["imperial","shogunate"],"winner":"imperial","short":"The last shogunate forces, who had sailed to Ezo and declared a republic, surrender at Hakodate in June 1869. The Boshin War is over."},{"id":"haihan","year":1871,"en":"The domains abolished","ja":"廃藩置県","at":"musashi","sides":[],"winner":null,"short":"With one decree the government abolishes the domains and replaces them with prefectures governed from Tokyo. The lords are pensioned off; the samurai's world ends."},{"id":"seinan","year":1877,"en":"The Satsuma Rebellion","ja":"西南戦争","at":"higo","sides":["empire","rebels"],"winner":"empire","short":"Saigō Takamori leads the former samurai of Satsuma against the government. The conscript army holds Kumamoto castle and wears the rebels down; Saigō dies at Shiroyama in September."},{"id":"ryukyu1879","year":1879,"en":"Ryukyu becomes Okinawa","ja":"琉球処分","at":"ryukyu","sides":[],"winner":null,"short":"Japan abolishes the kingdom of Ryukyu. Police and troops are sent to Shuri, the last king, Shō Tai, is moved to Tokyo, and the islands become Okinawa Prefecture."},{"id":"constitution","year":1889,"en":"The Meiji Constitution","ja":"大日本帝国憲法","at":"musashi","sides":[],"winner":null,"short":"The emperor grants Japan a written constitution, modelled largely on Prussia's, with an elected lower house but sovereignty resting with the emperor."},{"id":"sinojapanese","year":1894,"en":"The First Sino-Japanese War","ja":"日清戦争","at":"tsushima","sides":["empire"],"winner":"empire","short":"Japan and Qing China go to war over Korea. Japan wins on land and at sea and, by the treaty of Shimonoseki in 1895, takes Taiwan."},{"id":"tsushima1905","year":1905,"en":"The Battle of Tsushima","ja":"日本海海戦","at":"tsushima","sides":["empire"],"winner":"empire","short":"In the Russo-Japanese War, Admiral Tōgō Heihachirō's fleet destroys the Russian Baltic Fleet in the strait of Tsushima after its voyage halfway round the world."},{"id":"korea1910","year":1910,"en":"Korea annexed","ja":"韓国併合","at":"tsushima","sides":[],"winner":null,"short":"Japan annexes Korea, which it rules as a colony until 1945."},{"id":"kanto1923","year":1923,"en":"The Great Kantō earthquake","ja":"関東大震災","at":"sagami","sides":[],"winner":null,"short":"A great earthquake strikes Tokyo and Yokohama at midday on 1 September 1923; fires burn for days. Over 100,000 people die."},{"id":"manchuria","year":1931,"en":"The Manchurian Incident","ja":"満州事変","at":"tsushima","sides":["empire"],"winner":"empire","short":"Japanese army officers set off a small bomb by a railway line near Mukden, blame China, and seize Manchuria without orders from Tokyo. A puppet state, Manchukuo, follows in 1932."},{"id":"china1937","year":1937,"en":"War with China","ja":"日中戦争","at":"tsushima","sides":["empire"],"winner":null,"short":"A clash at the Marco Polo Bridge near Beijing becomes full-scale war. Japanese troops take Shanghai and Nanjing, where they massacre civilians and prisoners."},{"id":"pearl","year":1941,"en":"Pearl Harbor and the Pacific War","ja":"真珠湾攻撃","at":"musashi","sides":["empire"],"winner":null,"short":"Japanese carrier aircraft attack the US fleet at Pearl Harbor on 7 December 1941, while Japanese forces strike across Southeast Asia. Within months Japan holds an empire from Burma to the central Pacific."},{"id":"midway","year":1942,"en":"The Battle of Midway","ja":"ミッドウェー海戦","at":"musashi","sides":["empire"],"winner":null,"short":"In June 1942 American carrier aircraft sink four Japanese carriers near Midway atoll. From then on Japan is on the defensive."},{"id":"tokyo1945","year":1945,"en":"The firebombing of Tokyo","ja":"東京大空襲","at":"musashi","sides":["empire"],"winner":null,"short":"On the night of 9–10 March 1945 American bombers drop incendiaries on Tokyo. Some 90,000 to 100,000 people die in one night; most Japanese cities are burned in the months that follow."},{"id":"okinawa","year":1945,"en":"The Battle of Okinawa","ja":"沖縄戦","at":"ryukyu","sides":["empire"],"winner":null,"short":"From April to June 1945 the Americans fight to take Okinawa, south of Kyushu. Over 100,000 Okinawan civilians die, between a quarter and a third of the island's people."},{"id":"atomic","year":1945,"en":"Hiroshima and Nagasaki","ja":"原爆投下","at":"aki","sides":["empire"],"winner":null,"short":"On 6 August 1945 an American atomic bomb destroys Hiroshima; on 9 August a second destroys Nagasaki. By the end of the year about 140,000 people have died in Hiroshima and 74,000 in Nagasaki."},{"id":"surrender","year":1945,"en":"Japan surrenders","ja":"終戦","at":"musashi","sides":[],"winner":null,"short":"On 15 August 1945 Emperor Hirohito announces Japan's surrender by radio; on 2 September it is signed aboard USS Missouri in Tokyo Bay. The empire is over."}];
